// ---------- CONFIG ----------
// Find a board's ID by opening it in Trello, clicking the "..." menu -> "More" ->
// "Print, export, and share" -> "Export JSON", or just from the URL after visiting
// https://trello.com/1/members/me/boards?key=YOUR_KEY&token=YOUR_TOKEN
const BOARD_IDS = ['W7cGgwwY'];   // add more board IDs to combine multiple boards into one digest
// ----------------------------

return BOARD_IDS.map(boardId => ({ json: { boardId } }));

const items = $input.all();
const out = [];
for (const item of items) {
  if (Array.isArray(item.json)) {
    for (const c of item.json) out.push({ json: c });
  } else if (item.json && item.json.id) {
    out.push({ json: item.json });
  }
}
return out;

// ---------- CONFIG ----------
const DONE_LIST_NAMES = ['done', 'completed', 'shipped'];
const TZ = 'Asia/Manila';
const MAX_ROWS_PER_SECTION = 25;
// ----------------------------

const boards = $('Trello: Get Boards').all().map(i => i.json);
const lists = $('Trello: Get Lists').all().map(i => i.json);
const cards = $('Trello: Cards To Items').all().map(i => i.json);

const boardName = new Map(boards.map(b => [b.id, b.name]));
const listName = new Map(lists.map(l => [l.id, l.name]));
const listIsDone = new Map(lists.map(l => [l.id, DONE_LIST_NAMES.includes(String(l.name || '').trim().toLowerCase())]));

const now = Date.now();
const completed = [];
const overdue = [];

for (const c of cards) {
  const inDoneList = listIsDone.get(c.idList) === true;

  if (inDoneList || c.dueComplete === true) {
    completed.push({
      ...c,
      boardName: boardName.get(c.idBoard) || '(board)',
      listName: listName.get(c.idList) || ''
    });
  } else if (c.due) {
    const due = Date.parse(c.due);
    if (due < now) {
      overdue.push({
        ...c,
        boardName: boardName.get(c.idBoard) || '(board)',
        listName: listName.get(c.idList) || '',
        dueMs: due
      });
    }
  }
}

completed.sort((a, b) => String(a.name).localeCompare(String(b.name)));
overdue.sort((a, b) => a.dueMs - b.dueMs);

const esc = (s = '') => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linkText = (s = '') => esc(s).replace(/\|/g, '/');
const trunc = (s = '', n = 90) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const fmtDate = (ms) => new Intl.DateTimeFormat('en-US', { timeZone: TZ, month: 'short', day: 'numeric' }).format(new Date(ms));
const dateLabel = new Intl.DateTimeFormat('en-US', { timeZone: TZ, month: 'long', day: 'numeric', year: 'numeric' }).format(new Date());

const line = (c, showDue) => {
  const board = boards.length > 1 ? ` _(${esc(c.boardName)})_` : '';
  const due = showDue ? `  ⏰ was due ${fmtDate(c.dueMs)}` : '';
  return `• <${c.shortUrl}|${linkText(trunc(c.name, 80))}>${board}${due}`;
};

const sectionBlocks = (title, arr, showDue) => {
  if (!arr.length) return [{ type: 'section', text: { type: 'mrkdwn', text: `*${title}* — nothing to show.` } }];
  const shown = arr.slice(0, MAX_ROWS_PER_SECTION);
  const lines = shown.map(c => line(c, showDue));
  if (arr.length > shown.length) lines.push(`_…and ${arr.length - shown.length} more_`);
  return [{ type: 'section', text: { type: 'mrkdwn', text: `*${title}*\n${lines.join('\n')}` } }];
};

return [{
  json: {
    text: `Weekly digest: ${completed.length} completed, ${overdue.length} overdue`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: `📊 Weekly status digest — ${dateLabel}` } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: `Current Status  •  ✅ ${completed.length} completed  •  ⏰ ${overdue.length} overdue` }] },
      { type: 'divider' },
      ...sectionBlocks('✅ Completed Items', completed, false),
      { type: 'divider' },
      ...sectionBlocks('⏰ Overdue Items', overdue, true),
    ],
  },
}];
